// Room: D-pad run, C jump, B slash (UP + B upward), DOWN crouch, DOWN + C drop, START = floor map.
// Map:  START back, A run/stop the Void, B show everything (debug), C new floor.

enum { MODE_ROOM, MODE_MAP };

#define MAP_X 2
#define MAP_Y 4

static Level lv;
static Player player;
static u8 mode = MODE_ROOM;
static u8 depth = 1;
static bool showSecrets = FALSE;
static u16 deathFrames;      // > 0 while the death message is shown

// ---------------------------------------------------------------- floor map

static const char LETTER[] = { ' ', '.', 'S', 'B', 'U', '$', '?', '!' };


static void drawCell(u8 x, u8 y)
{
    u8 t = lv.floor.type[y][x];
    u8 secret = t == ROOM_SECRET || t == ROOM_SUPER_SECRET;
    if (t == ROOM_NONE || (secret && !showSecrets && !lv.visited[y][x])) return;

    // Like Isaac: visited rooms are known, rooms behind a visible door of a visited room are guessed.
    u8 known = showSecrets || lv.visited[y][x];
    u8 guessed = (x > 0 && lv.visited[y][x - 1] && (level_doors(&lv, x - 1, y) & DOOR_RIGHT))
        || (x < FLOOR_W - 1 && lv.visited[y][x + 1] && (level_doors(&lv, x + 1, y) & DOOR_LEFT))
        || (y > 0 && lv.visited[y - 1][x] && (level_doors(&lv, x, y - 1) & DOOR_DOWN))
        || (y < FLOOR_H - 1 && lv.visited[y + 1][x] && (level_doors(&lv, x, y + 1) & DOOR_UP));
    if (!known && !guessed) return;

    u16 px = MAP_X + x * 4, py = MAP_Y + y * 3;
    u16 pal = PAL0;
    if (t == ROOM_BOSS) pal = PAL1;
    else if (t >= ROOM_UPGRADE) pal = PAL2;
    if (!secret && level_cellInVoid(&lv, x, y)) pal = PAL3;

    char cell[4] = { '[', known ? LETTER[t] : ' ', ']', 0 };
    if (x == lv.cellX && y == lv.cellY) cell[1] = '@';
    VDP_setTextPalette(pal);
    VDP_drawText(cell, px, py);

    // Doors are drawn by the room on their left/top side only.
    u8 doors = level_doors(&lv, x, y), hidden = showSecrets ? lv.floor.hidden[y][x] & ~lv.opened[y][x] : 0;
    if (!known)   // only the doors leading back to visited rooms
    {
        if (!(x < FLOOR_W - 1 && lv.visited[y][x + 1])) doors &= ~DOOR_RIGHT;
        if (!(y < FLOOR_H - 1 && lv.visited[y + 1][x])) doors &= ~DOOR_DOWN;
    }
    VDP_setTextPalette(PAL0);
    if (doors & DOOR_RIGHT) VDP_drawText("-", px + 3, py);
    if (doors & DOOR_DOWN) VDP_drawText("|", px + 1, py + 1);
    VDP_setTextPalette(PAL2);
    if (hidden & DOOR_RIGHT) VDP_drawText("=", px + 3, py);
    if (hidden & DOOR_DOWN) VDP_drawText(":", px + 1, py + 1);
}

static void drawMapStatus(void)
{
    char line[41];
    VDP_setTextPalette(PAL0);
    sprintf(line, "GRAINE %04X  ETAGE %u  SALLES %u   ", lv.floor.seed, depth, lv.floor.roomCount);
    VDP_drawText(line, 2, 2);
    sprintf(line, "NEANT R=%4u %s   ", (u16) (lv.voidRadiusFx >> 8), lv.voidRunning ? "AVANCE" : "ARRET ");
    VDP_drawText(line, 2, 27);
}

static void drawMap(void)
{
    VDP_clearPlane(BG_A, TRUE);
    VDP_clearPlane(BG_B, TRUE);
    VDP_setTextPalette(PAL0);
    VDP_drawText("CARTE  START retour", 2, 0);
    VDP_drawText("A neant  B tout voir  C nouvel etage", 2, 1);
    for (u8 y = 0; y < FLOOR_H; y++)
        for (u8 x = 0; x < FLOOR_W; x++) drawCell(x, y);
    drawMapStatus();
}

static void newFloor(u16 seed)
{
    level_start(&lv, &player, seed, depth);
}

static void updateMap(u16 pressed)
{
    if (pressed & BUTTON_C)
    {
        depth = depth % 6 + 1;
        newFloor(random() ^ vtimer);
        drawMap();
    }
    if (pressed & BUTTON_B)
    {
        showSecrets = !showSecrets;
        drawMap();
    }
    if (pressed & BUTTON_A)
    {
        lv.voidRunning = !lv.voidRunning && lv.voidRadiusFx;
        drawMapStatus();
    }
}

// ---------------------------------------------------------------- room

// Camera: the room is streamed into a 64 x 32 tile plane that wraps around. Only the visible
// 41 x 29 tiles must be valid, so each step of one tile redraws one column or one row.
static s16 camX, camY;          // top-left of the screen, room pixels
static s16 drawnTX, drawnTY;    // camera tile the plane currently matches

// The Void circle on screen: for each visible row, the room columns inside the circle form one
// interval [in0, in1). One square root per row gives it, so the edge costs almost nothing and only
// the tiles crossing it are rewritten. Inside: high priority (normal). Outside: low priority, which
// the shadow/highlight mode draws at half brightness: the castle is seen through the Void, darkened.
static s16 rowRoomY[32];          // room row currently held by each plane row
static s16 rowIn0[32], rowIn1[32];

static u16 isqrt32(u32 v)
{
    u16 lo = 0, hi = 0xFFFF;
    while (lo < hi)
    {
        u16 mid = lo + (hi - lo + 1) / 2;
        if ((u32) mid * mid <= v) lo = mid;
        else hi = mid - 1;
    }
    return lo;
}

static void rowInterval(s16 ty, s16 *in0, s16 *in1)
{
    s16 r = lv.voidRadiusFx >> 8;
    s16 wy = lv.cellY * CELL_H_PX + ty * 8 + 4 - lv.voidCY;
    if (wy > r || -wy > r)
    {
        *in0 = *in1 = 0;
        return;
    }
    s16 half = isqrt32((u32) r * r - (u32) ((s32) wy * wy));
    s16 cx = lv.voidCX - lv.cellX * CELL_W_PX;   // circle centre in room pixels
    *in0 = (cx - half - 4 + 7) >> 3;             // first tile whose centre is inside
    *in1 = ((cx + half - 4) >> 3) + 1;
}
static u8 roomTile(s16 tx, s16 ty)
{
    if (tx < 0 || ty < 0 || tx >= lv.room.w || ty >= lv.room.h) return TILE_SOLID;   // walls go on
    return lv.room.tiles[ty][tx];
}

// Room tile or decor for a room cell (decor_planeTile, game_decor.c), or a cracked wall hiding a
// secret room.
static u16 castleTile(s16 tx, s16 ty)
{
    if (lv.crackedCount && roomTile(tx, ty) == TILE_SOLID && level_crackedAt(&lv, tx * 8 + 4, ty * 8 + 4))
        return CASTLE_CRACKED + ((ty & 1) << 1 | (tx & 1));
    return decor_planeTile(&lv.room, tx, ty);
}

// Room tiles stay in front (high priority) unless the Void has swallowed them: the shadow mode then
// darkens them. Empty tiles show the decor (trees, graves, fence), with the same priority.
static void drawTileState(s16 tx, s16 ty, u8 inVoid)
{
    u16 index = castleTile(tx, ty), tile = 0;
    if (index & DECOR_TILE) tile = gfx_decorTile(index & 0xFF);
    else if (index & ~CASTLE_FLIP) tile = GFX_CASTLE + (index & ~CASTLE_FLIP);
    VDP_setTileMapXY(ROOM_PLANE, TILE_ATTR_FULL(PAL0, !inVoid, 0, (index & CASTLE_FLIP) != 0, tile), tx & 63, ty & 31);
}

static void drawColumn(s16 tx)
{
    for (s16 ty = drawnTY; ty <= drawnTY + SCREEN_H_TILES; ty++)
    {
        u8 cy = ty & 31;
        drawTileState(tx, ty, tx < rowIn0[cy] || tx >= rowIn1[cy]);
    }
}

static void drawRow(s16 ty)
{
    u8 cy = ty & 31;
    rowInterval(ty, &rowIn0[cy], &rowIn1[cy]);
    rowRoomY[cy] = ty;
    for (s16 tx = drawnTX; tx <= drawnTX + SCREEN_W_TILES; tx++)
        drawTileState(tx, ty, tx < rowIn0[cy] || tx >= rowIn1[cy]);
}
static void updateCamera(void)
{
    // Dead zone: the camera only moves when the ninja leaves a box around the screen centre.
    s16 px = player.x >> 8, py = player.y >> 8;
    if (px < camX + 144) camX = px - 144;
    if (px > camX + 176) camX = px - 176;
    if (py < camY + 96) camY = py - 96;
    if (py > camY + 160) camY = py - 160;

    s16 maxX = lv.room.w * ROOM_TILE - SCREEN_W_TILES * ROOM_TILE;
    s16 maxY = lv.room.h * ROOM_TILE - SCREEN_H_TILES * ROOM_TILE;
    if (camX > maxX) camX = maxX;
    if (camY > maxY) camY = maxY;
    if (camX < 0) camX = 0;
    if (camY < 0) camY = 0;
}

// Parallax (the line scroll mode, one horizontal offset per screen line): FAR_PLANE is cut into bands
// of rows (far_bands.h, written with the picture by tools/art/make_art.py), from the high clouds to
// the forest, each drifting at its own fraction of the room's speed. It is 256 rows tall: its
// vertical offset follows the camera from the top of the room (0) to the bottom (32), so it never
// wraps. Both tables go to video memory by DMA during the next vertical blank.
static s16 scrollRoom[224], scrollBands[224];
static void scrollFar(void)
{
    s16 maxY = lv.room.h * ROOM_TILE - SCREEN_H_TILES * ROOM_TILE;
    s16 vB = maxY > 0 ? (s16) ((u32) camY * 32 / (u16) maxY) : 32;
    u16 worldX = lv.cellX * CELL_W_PX + camX;
    s16 band[FAR_BANDS];
    for (u8 b = 0; b < FAR_BANDS; b++)
        band[b] = -(s16) (((u32) worldX * FAR_BAND_SPEED[b]) >> 5) - FAR_BAND_DRIFT[b] * (s16) (vtimer >> 4);
    u8 b = 0;
    for (u16 line = 0; line < 224; line++)
    {
        u16 row = line + vB;
        while (b < FAR_BANDS - 1 && row >= FAR_BAND_END[b]) b++;
        scrollRoom[line] = -camX;
        scrollBands[line] = band[b];
    }
    VDP_setHorizontalScrollLine(ROOM_PLANE, 0, scrollRoom, 224, DMA_QUEUE);
    VDP_setHorizontalScrollLine(FAR_PLANE, 0, scrollBands, 224, DMA_QUEUE);
    VDP_setVerticalScroll(FAR_PLANE, vB);
}

static void scrollCamera(void)
{
    s16 tx = camX >> 3, ty = camY >> 3;
    while (drawnTX < tx) { drawnTX++; drawColumn(drawnTX + SCREEN_W_TILES); }
    while (drawnTX > tx) { drawnTX--; drawColumn(drawnTX); }
    while (drawnTY < ty) { drawnTY++; drawRow(drawnTY + SCREEN_H_TILES); }
    while (drawnTY > ty) { drawnTY--; drawRow(drawnTY); }
    VDP_setVerticalScroll(ROOM_PLANE, camY);
    scrollFar();
}

// Each frame: new interval per visible row, rewrite only the columns between the old and new edges.
static void rewriteSpan(s16 ty, s16 a, s16 b, s16 in0, s16 in1)
{
    if (a > b) { s16 t = a; a = b; b = t; }
    if (a < drawnTX) a = drawnTX;
    if (b > drawnTX + SCREEN_W_TILES + 1) b = drawnTX + SCREEN_W_TILES + 1;
    for (s16 tx = a; tx < b; tx++) drawTileState(tx, ty, tx < in0 || tx >= in1);
}

static void refreshVoid(void)
{
    for (s16 ty = drawnTY; ty <= drawnTY + SCREEN_H_TILES; ty++)
    {
        u8 cy = ty & 31;
        s16 in0, in1;
        rowInterval(ty, &in0, &in1);
        if (in0 == rowIn0[cy] && in1 == rowIn1[cy]) continue;
        if (in0 >= in1 || rowIn0[cy] >= rowIn1[cy])
            rewriteSpan(ty, rowIn0[cy] < rowIn1[cy] ? rowIn0[cy] : in0, rowIn0[cy] < rowIn1[cy] ? rowIn1[cy] : in1, in0, in1);
        else
        {
            rewriteSpan(ty, rowIn0[cy], in0, in0, in1);
            rewriteSpan(ty, rowIn1[cy], in1, in0, in1);
        }
        rowIn0[cy] = in0;
        rowIn1[cy] = in1;
    }
}
// Middle of the open trapdoor of the room, room pixels (trapX < 0: none). Its plank looks like any
// other, so an arrow floats over it. Templates keep their two bottom rows of blocks for the floor: a
// plank there can only be the cover of the hole. Looked up again each time the room is drawn, so the
// arrow goes when the boss locks the doors.
static s16 trapX, trapY;

static void findTrapdoor(void)
{
    s16 ty = lv.room.h - 4, first = -1, last = -1;
    for (s16 tx = 0; tx < lv.room.w; tx++)
        if (lv.room.tiles[ty][tx] == TILE_PLATFORM)
        {
            if (first < 0) first = tx;
            last = tx;
        }
    trapX = first < 0 ? -1 : (first + last + 1) * 4;
    trapY = ty * 8;
}

// Decor of the room drawn last (cell index; 0xFF: none). Placed again on a room change only: a
// door crossing redraws through drawRoom, not enterRoom, and kept the last room's fences and graves,
// floating in the new one (Thomas); a wall broken open must not move them.
static u8 decorCell = 0xFF;

static void drawRoom(void)
{
    u8 cell = lv.cellY * FLOOR_W + lv.cellX;
    if (cell != decorCell)
    {
        decorCell = cell;
        decor_place(&lv.room, lv.floor.seed ^ (lv.cellX * 77 + lv.cellY * 1031));
    }
    findTrapdoor();
    updateCamera();
    drawnTX = camX >> 3;
    drawnTY = camY >> 3;
    for (s16 ty = drawnTY; ty <= drawnTY + SCREEN_H_TILES; ty++) drawRow(ty);
    scrollCamera();
}

// Sprites: 0 hero, 1 slash, 2.. enemies, then shots, gem, item, props, pickups, rest of the hero.
// An enemy pose is 1 to 4 sprites. The console shows 80 sprites in all: the enemies share a pool
// instead of owning 4 each (12 enemies never show their widest pose on one screen together).
#define SPRITE_ENEMIES 2
#define ENEMY_SPRITES 35
#define SPRITE_SHOTS (SPRITE_ENEMIES + ENEMY_SPRITES)
#define SPRITE_GEM (SPRITE_SHOTS + MAX_SHOTS)
#define SPRITE_ITEM (SPRITE_GEM + 1)
#define SPRITE_TRAP (SPRITE_ITEM + 1)     // arrow over the trapdoor
#define SPRITE_PROPS (SPRITE_TRAP + 1)
#define SPRITE_PICKUPS (SPRITE_PROPS + MAX_PROPS)
#define SPRITE_EXT2 (SPRITE_PICKUPS + MAX_PICKUPS)   // second extension cell of the hero
#define SPRITE_EXT3 (SPRITE_EXT2 + 1)       // third one (big slash crescents)
#define SPRITE_BODY_LOW (SPRITE_EXT3 + 1)   // hero below row 32 (hardware sprites are 4 x 4 tiles max)
#define SPRITE_HIT (SPRITE_BODY_LOW + 1)    // spark of a blow; chained right after the hero, over the enemies
#define SPRITE_HUD (SPRITE_HIT + 1)        // 10 sprites: hearts 3, light 3, coins, minimap 2, keys
#define SPRITE_COUNT (SPRITE_HUD + 10)

// Animation frame from the player's state. Running advances one frame every 7 px travelled,
// so the legs match the ground speed (and the upgrades that change it).
static u8 ninjaFrame(void)
{
    static u16 runDistance;
    static u8 runFrame, landTimer, wasOnGround = 1;
    if (player.onGround && !wasOnGround) landTimer = 5;
    wasOnGround = player.onGround;
    if (landTimer) landTimer--;
    if (player.hurtTimer) return NINJA_HURT;
    // The slash shows only its wind-up and its crescent: no end pose, the recovery (no new slash yet)
    // keeps the normal animation (Thomas, 2026-11-17).
    if (player.attackTimer && player_attackStep(&player) < 3)
    {
        u8 step = player_attackStep(&player);
        if (player.attackDir == ATTACK_UP) return NINJA_UP0 + step;
        if (player.attackDir == ATTACK_DOWN) return NINJA_DOWN0 + step;
        if (player.crouching) return step == 1 || step == 2 ? NINJA_CROUCH_SLASH1 : NINJA_CROUCH_SLASH0;
        if (!player.onGround) return NINJA_AIR0 + step;
        return NINJA_SLASH0 + step;
    }
    if (player.crouching) return NINJA_CROUCH;
    if (!player.onGround)
    {
        if (player.vy < -320) return NINJA_RISE;
        if (player.vy > 320) return NINJA_FALL;
        return NINJA_FLIP0 + ((vtimer >> 2) & 3);   // somersault at the peak
    }
    if (landTimer) return NINJA_LAND;
    s16 speed = player.vx < 0 ? -player.vx : player.vx;
    if (speed < 96)
    {
        runDistance = 0;
        return NINJA_IDLE0 + ((vtimer >> 4) & 3);
    }
    runDistance += speed;   // no division in the frame loop: step the frame every 7 px
    while (runDistance >= 7 * 256)
    {
        runDistance -= 7 * 256;
        runFrame = (runFrame + 1) & 7;
    }
    return NINJA_RUN0 + runFrame;
}

typedef struct
{
    u8 count, first;
    s8 x[3], y[3];
} HeroExt;

// Rooms are several screens wide and the VDP's sprite coordinates wrap around every 512 pixels: what
// is far from the camera must be hidden, or it shows up again as a ghost on screen. (x, y) = top-left
// of a sprite of 32 x 48 at most, in screen pixels.
static u8 offScreen(s16 x, s16 y)
{
    return x < -32 || x > 320 || y < -48 || y > 224;
}
static const HeroExt HERO_EXT[NINJA_FRAME_COUNT] = NINJA_EXT_TABLE;

typedef struct
{
    u16 tile;       // first tile, from GFX_ENEMIES
    s8 dx, dy;      // cell from the enemy's centre (facing right) and from just below its feet
    u8 parts;       // see enemy_frames.h
} EnemyFrame;

static const EnemyFrame ENEMY_FRAME[EF_COUNT] = ENEMY_FRAME_TABLE;

// Drawing of each pose (ENEMY_POSE_*) of each enemy; the boss and the small jelly are drawn apart.
static const u8 POSE_FRAME[ENEMY_TYPES][ENEMY_POSES] =
{
    { 0, 0, 0, 0, 0 },
    { EF_SOLDIER_WALK_A, EF_SOLDIER_WALK_B, EF_SOLDIER_WINDUP, EF_SOLDIER_STRIKE, EF_SOLDIER_STRIKE },
    { EF_SPECTRE_FLOAT_A, EF_SPECTRE_FLOAT_B, EF_SPECTRE_LUNGE, EF_SPECTRE_LUNGE, EF_SPECTRE_LUNGE },
    { 0, 0, 0, 0, 0 },
    { EF_ARCHER_IDLE, EF_ARCHER_IDLE, EF_ARCHER_AIM, EF_ARCHER_RELEASE, EF_ARCHER_RELEASE },
    { 0, 0, 0, 0, 0 },   // ninja: out for now, no drawing (never spawned)
    { EF_GUARD_WALK_A, EF_GUARD_WALK_B, EF_GUARD_WINDUP, EF_GUARD_THRUST, EF_GUARD_UP },
    { EF_JELLY_SQUASH, EF_JELLY_STRETCH, EF_JELLY_SQUASH, EF_JELLY_STRETCH, EF_JELLY_STRETCH },
    { 0, 0, 0, 0, 0 },
};

// One pose = up to four sprites side by side (tools/art/enemies.py). Mirrored, the cell flips around
// the enemy's centre, so each part goes to the other side. Returns the next free sprite.
static u8 drawEnemyFrame(u8 n, const EnemyFrame *f, s16 cx, s16 feetY, u16 base, u8 flip)
{
    static const u8 PX[4] = { 0, 32, 0, 32 }, PY[4] = { 0, 0, 32, 32 }, TILES_H[4] = { 4, 4, 2, 2 };
    u8 strip = (f->parts & 0x10) ? 2 : 1;
    u16 tile = GFX_ENEMIES + f->tile;
    for (u8 k = 0; k < 4; k++)
    {
        if (!(f->parts & (1 << k))) continue;
        u8 w = (k & 1) ? strip : 4;
        if (n < SPRITE_ENEMIES + ENEMY_SPRITES)
        {
            s16 x = flip ? cx - f->dx - PX[k] - w * 8 : cx + f->dx + PX[k];
            VDP_setSpriteFull(n, x, feetY + f->dy + PY[k], SPRITE_SIZE(w, TILES_H[k]), base + tile, n + 1);
            n++;
        }
        tile += w * TILES_H[k];
    }
    return n;
}

// The icon of an upgrade (PixelLab, one each); the old relic for anything else.
static u16 itemTile(u8 item)
{
    return item >= ITEM_FIRST_UPGRADE && item < ITEM_COUNT ? GFX_ITEMS + (item - ITEM_FIRST_UPGRADE) * 4 : GFX_TILE_RELIC;
}

static void drawSprites(void)
{
    static u8 loadedFrame = 0xFF;
    s16 px = (player.x >> 8) - camX, py = (player.y >> 8) - camY;
    u16 flip = player.facingLeft;
    u8 f = ninjaFrame();
    const HeroExt *ext = &HERO_EXT[f];
    if (f != loadedFrame)
    {
        // Stream the frame's tiles (and its slash arcs) into VRAM during the next vblank.
        loadedFrame = f;
        // The sheet stores each frame as 4 columns of 6 tiles: split them into a 4 x 4 top sprite
        // (GFX_NINJA) and a 4 x 2 bottom one (GFX_NINJA + 16), both in hardware column order.
        const u32 *src = ts_ninja.tiles + (u32) f * 24 * 8;
        for (u8 c = 0; c < 4; c++)
        {
            VDP_loadTileData(src + c * 6 * 8, GFX_NINJA + c * 4, 4, DMA_QUEUE);
            VDP_loadTileData(src + (c * 6 + 4) * 8, GFX_NINJA + 16 + c * 2, 2, DMA_QUEUE);
        }
        if (ext->count)
            VDP_loadTileData(ts_ninja_fx.tiles + (u32) ext->first * 16 * 8, GFX_NINJA_EXT,
                             (ext->count > 2 ? 2 : ext->count) * 16, DMA_QUEUE);
        if (ext->count > 2)   // the third cell lives apart, at the very end of video memory
            VDP_loadTileData(ts_ninja_fx.tiles + (u32) (ext->first + 2) * 16 * 8, GFX_NINJA_EXT3, 16, DMA_QUEUE);
    }
    // The hero's sprites come first in the chain (in front of everything): body, lower body, slash
    // arcs, then the spark, the enemies... the pickups last. (The lower body used to come last: a
    // ware was drawn over the hero's legs and under his chest.)
    // Sprite 0: hero (32 x 48, body centred on x 16, soles on row GFX_HERO_FEET); blinks while invulnerable.
    u8 hidden = (player.invulnerable & 4) != 0;
    s16 bx = px - 16, by = py - GFX_HERO_FEET - 1;
    VDP_setSpriteFull(0, bx, hidden ? -64 : by, SPRITE_SIZE(4, 4), TILE_ATTR_FULL(PAL1, 1, 0, flip, GFX_NINJA), SPRITE_BODY_LOW);
    VDP_setSpriteFull(SPRITE_BODY_LOW, bx, hidden ? -64 : by + 32, SPRITE_SIZE(4, 2),
                      TILE_ATTR_FULL(PAL1, 1, 0, flip, GFX_NINJA + 16), 1);

    // Sprites 1, SPRITE_EXT2 and SPRITE_EXT3: 32 x 32 extension cells (slash arcs), mirrored with the body.
    static const u8 EXT_SPRITE[3] = { 1, SPRITE_EXT2, SPRITE_EXT3 };
    static const u8 EXT_LINK[3] = { SPRITE_EXT2, SPRITE_EXT3, SPRITE_HIT };
    for (u8 k = 0; k < 3; k++)
    {
        s16 ex = flip ? bx - ext->x[k] : bx + ext->x[k];
        s16 ey = (k < ext->count && !hidden) ? by + ext->y[k] : -64;
        u16 tile = k < 2 ? GFX_NINJA_EXT + k * 16 : GFX_NINJA_EXT3;
        VDP_setSpriteFull(EXT_SPRITE[k], ex, ey, SPRITE_SIZE(4, 4), TILE_ATTR_FULL(PAL1, 1, 0, flip, tile), EXT_LINK[k]);
    }

    // Spark where the last blow landed: big for two frames, then mirrored each frame so it flickers.
    // A blocked blow gives the same spark in the Void's cold colours.
    {
        const EnemySet *s = &lv.enemies;
        s16 hx = s->hitX - camX - 8, hy = s->hitY - camY - 8;
        if (!s->hitTimer || offScreen(hx, hy)) hy = -64;
        VDP_setSpriteFull(SPRITE_HIT, hx, hy, SPRITE_SIZE(2, 2),
                          TILE_ATTR_FULL(s->hitBlocked ? PAL3 : PAL2, 1, s->hitTimer & 1, (s->hitTimer >> 1) & 1, GFX_TILE_HIT),
                          SPRITE_ENEMIES);
    }

    // Enemies, from the pool of sprites. Flashing when hurt, fast blinking while the death puff plays.
    u8 n = SPRITE_ENEMIES;
    for (u8 i = 0; i < MAX_ENEMIES; i++)
    {
        const Enemy *e = &lv.enemies.e[i];
        s16 ex = (e->x >> 8) - camX, ey = (e->y >> 8) - camY;
        // The widest pose reaches 48 px from the centre, on either side once mirrored.
        if (e->type == ENEMY_NONE || (e->deathTimer && (e->deathTimer & 2)) || (!e->flashTimer && (e->hurtTimer & 2))
            || (e->type == ENEMY_BOSS && e->state == BOSS_DASH_WARN && (e->stateTimer & 4))
            || ex < -48 || ex > 368 || ey < 0 || ey > 272)
            continue;
        // Void form: the same tiles with PAL3 (the enemies' colours swallowed by the Void).
        // Just hit: the other palette for a few frames, a flash of colour that cannot be missed.
        u16 base = TILE_ATTR_FULL((e->voidForm != 0) != (e->flashTimer != 0) ? PAL3 : PAL2, 1, 0, e->facingLeft, 0);
        if (e->type == ENEMY_JELLY_SMALL)
        {
            if (n < SPRITE_ENEMIES + ENEMY_SPRITES)
            {
                VDP_setSpriteFull(n, ex - 4, ey - 7, SPRITE_SIZE(1, 1), base + GFX_TILE_JELLY_SMALL, n + 1);
                n++;
            }
        }
        else if (e->type == ENEMY_BOSS)
        {
            // 32 x 48 in two sprites: feet on pixel row 45 of the doubled walker art.
            if (n + 1 < SPRITE_ENEMIES + ENEMY_SPRITES)
            {
                VDP_setSpriteFull(n, ex - 16, ey - 46, SPRITE_SIZE(4, 4), base + GFX_TILE_BOSS_TOP, n + 1);
                VDP_setSpriteFull(n + 1, ex - 16, ey - 14, SPRITE_SIZE(4, 2), base + GFX_TILE_BOSS_BOTTOM, n + 2);
                n += 2;
            }
        }
        else
        {
            // The guard's crescent (tools/art/slash.py), in front of its body: side 32 x 48, up 48 x 32.
            if (e->slash && n + 1 < SPRITE_ENEMIES + ENEMY_SPRITES)
            {
                u16 attr = base + GFX_ENEMY_SLASH;
                if (e->slash == GUARD_SLASH_SIDE)
                {
                    s16 sx = e->facingLeft ? ex - 2 - 32 : ex + 2;
                    VDP_setSpriteFull(n, sx, ey - 50, SPRITE_SIZE(4, 4), attr, n + 1);
                    VDP_setSpriteFull(n + 1, sx, ey - 18, SPRITE_SIZE(4, 2), attr + 16, n + 2);
                }
                else
                {
                    s16 l = ex - 24, rx = ex + 8;   // mirrored, the 32 px part goes to the right
                    if (e->facingLeft) { l = ex + 24 - 32; rx = ex - 24; }
                    VDP_setSpriteFull(n, l, ey - 84, SPRITE_SIZE(4, 4), attr + 24, n + 1);
                    VDP_setSpriteFull(n + 1, rx, ey - 84, SPRITE_SIZE(2, 4), attr + 40, n + 2);
                }
                n += 2;
            }
            n = drawEnemyFrame(n, &ENEMY_FRAME[POSE_FRAME[e->type][e->pose]], ex, ey, base, e->facingLeft);
        }
    }
    // The exit door, once the boss is gone: on the boss's tiles, given back on the next floor.
    {
        static u8 doorLoaded;
        u8 bossThere = 0;
        for (u8 i = 0; i < MAX_ENEMIES; i++) bossThere |= lv.enemies.e[i].type == ENEMY_BOSS;
        if (lv.exitOpen && !bossThere)
        {
            if (!doorLoaded) gfx_loadDoor();
            doorLoaded = 1;
            s16 dx = lv.exitX - camX - 16, dy = lv.exitY - camY - 48;
            if (n + 1 < SPRITE_ENEMIES + ENEMY_SPRITES && !offScreen(dx, dy))
            {
                VDP_setSpriteFull(n, dx, dy, SPRITE_SIZE(4, 4), TILE_ATTR_FULL(PAL2, 0, 0, 0, GFX_TILE_BOSS_TOP), n + 1);
                VDP_setSpriteFull(n + 1, dx, dy + 32, SPRITE_SIZE(4, 2), TILE_ATTR_FULL(PAL2, 0, 0, 0, GFX_TILE_BOSS_BOTTOM), n + 2);
                n += 2;
            }
        }
        else if (doorLoaded && !lv.exitOpen)
        {
            gfx_loadBoss();
            doorLoaded = 0;
        }
    }
    // The padlock on the upgrade room's door, until a key opens it.
    if (lv.cellX == lv.lockX && lv.cellY == lv.lockY && !lv.lockOpen && n < SPRITE_ENEMIES + ENEMY_SPRITES)
    {
        s16 lx = lv.padlockX - camX - 8, ly = lv.padlockY - camY - 8;
        if (offScreen(lx, ly)) ly = -64;
        VDP_setSpriteFull(n, lx, ly, SPRITE_SIZE(2, 2), TILE_ATTR_FULL(PAL2, 1, 0, 0, GFX_PADLOCK), n + 1);
        n++;
    }
    // The merchant's caravan in its room, the merchant in the shop (on the chests' tiles).
    {
        static u8 shopArt;
        u8 inCar = lv.cellX == lv.carX && lv.cellY == lv.carY, inShop = lv.cellX == lv.shopX && lv.cellY == lv.shopY;
        if ((inCar || inShop) != shopArt)
        {
            shopArt = inCar || inShop;
            gfx_loadShop(shopArt);
        }
        if (inCar && n + 3 < SPRITE_ENEMIES + ENEMY_SPRITES)
        {
            s16 cx = lv.caravanX - camX - 32, cy = lv.caravanY - camY - 64;
            for (u8 k = 0; k < 4; k++)
            {
                s16 sx = cx + (k >> 1) * 32, sy = cy + (k & 1) * 32;
                if (offScreen(sx, sy)) sy = -64;
                VDP_setSpriteFull(n, sx, sy, SPRITE_SIZE(4, 4), TILE_ATTR_FULL(PAL2, 0, 0, 0, GFX_CARAVAN + k * 16), n + 1);
                n++;
            }
        }
        if (inShop && n + 1 < SPRITE_ENEMIES + ENEMY_SPRITES)
        {
            s16 mx = lv.room.w * ROOM_TILE - MERCHANT_X_FROM_RIGHT - camX - 16;
            s16 my = lv.room.h * ROOM_TILE - 2 * 16 - camY - 48 + ((vtimer >> 5) & 1);   // breathing
            VDP_setSpriteFull(n, mx, my, SPRITE_SIZE(4, 4), TILE_ATTR_FULL(PAL2, 0, 0, 0, GFX_MERCHANT), n + 1);
            VDP_setSpriteFull(n + 1, mx, my + 32, SPRITE_SIZE(4, 2), TILE_ATTR_FULL(PAL2, 0, 0, 0, GFX_MERCHANT + 16), n + 2);
            n += 2;
        }
    }
    // The rest of the pool stays in the chain (the sprites after it are fixed), out of sight.
    for (; n < SPRITE_ENEMIES + ENEMY_SPRITES; n++) VDP_setSpriteFull(n, 0, -64, SPRITE_SIZE(1, 1), 0, n + 1);
    for (u8 i = 0; i < MAX_SHOTS; i++)
    {
        const Shot *sh = &lv.enemies.shots[i];
        u8 arrow = sh->kind == SHOT_ARROW;
        s16 half = arrow ? 12 : 4;
        s16 sx = (sh->x >> 8) - camX - half, y = (sh->y >> 8) - camY - half;
        if (!sh->active || offScreen(sx, y)) y = -64;
        u16 tile = sh->kind == SHOT_SHURIKEN ? GFX_TILE_SHURIKEN : GFX_TILE_SHOT;
        u16 spal = sh->kind == SHOT_SPORE ? PAL3 : PAL2;
        u16 hflip = sh->vx < 0, vflip = sh->kind == SHOT_SHURIKEN && (vtimer & 4);   // shurikens spin
        if (arrow)
        {
            // The drawing nearest its flight (0, 22.5, 45, 67.5, 90 degrees up), mirrored: tan 11.25,
            // 33.75, 56.25 and 78.75 degrees are about 1/5, 2/3, 3/2 and 5.
            s32 ax = sh->vx < 0 ? -sh->vx : sh->vx, ay = sh->vy < 0 ? -sh->vy : sh->vy;
            u8 k = ay * 5 < ax ? 0 : ay * 3 < ax * 2 ? 1 : ay * 2 < ax * 3 ? 2 : ay < ax * 5 ? 3 : 4;
            tile = GFX_ARROWS + k * 9;
            vflip = sh->vy > 0;
        }
        VDP_setSpriteFull(SPRITE_SHOTS + i, sx, y, arrow ? SPRITE_SIZE(3, 3) : SPRITE_SIZE(1, 1),
                          TILE_ATTR_FULL(spal, 1, vflip, hflip, tile), SPRITE_SHOTS + i + 1);
    }
    s16 gx = (lv.gemX >> 8) - camX - 4, gy = (lv.gemY >> 8) - camY - 8;
    if (!lv.gemActive || offScreen(gx, gy)) gy = -64;
    VDP_setSpriteFull(SPRITE_GEM, gx, gy, SPRITE_SIZE(1, 1),
                      TILE_ATTR_FULL(PAL3, 1, 0, 0, GFX_TILE_GEM), SPRITE_ITEM);

    // Item on its altar, bobbing gently.
    s16 bob = ((vtimer >> 3) & 7) < 4 ? 0 : 1;
    u8 itemShown = lv.itemId && !offScreen(lv.itemX - camX - 8, lv.itemY - camY - 20);
    if (lv.itemId == ITEM_HEART)
        VDP_setSpriteFull(SPRITE_ITEM, lv.itemX - camX - 4, itemShown ? lv.itemY - camY - 12 - bob : -64,
                          SPRITE_SIZE(1, 1), TILE_ATTR_FULL(PAL1, 1, 0, 0, GFX_TILE_HEART), SPRITE_TRAP);
    else
        VDP_setSpriteFull(SPRITE_ITEM, lv.itemX - camX - 8, itemShown ? lv.itemY - camY - 20 - bob : -64,
                          SPRITE_SIZE(2, 2), TILE_ATTR_FULL(PAL2, 1, 0, 0, itemTile(lv.itemId)), SPRITE_TRAP);

    // Arrow over the trapdoor, dipping towards it.
    s16 ax = trapX - camX - 8, ay = trapY - camY - 22 + ((vtimer >> 3) & 3);
    if (trapX < 0 || offScreen(ax, ay)) ay = -64;
    VDP_setSpriteFull(SPRITE_TRAP, ax, ay, SPRITE_SIZE(2, 2), TILE_ATTR_FULL(PAL2, 1, 0, 0, GFX_TILE_TRAP_ARROW),
                      SPRITE_PROPS);

    for (u8 i = 0; i < MAX_PROPS; i++)
    {
        const Prop *pr = &lv.props[i];
        u8 chest = pr->type >= PROP_CHEST_BRONZE, crate = pr->type == PROP_CRATE;
        u8 half = chest || crate ? 16 : 8;   // chests and crates: 32 x 32, props: 16 x 16, bottom-centred
        u8 shown = i < lv.propCount && (pr->alive || chest)   // opened chests stay, open
            && !offScreen(pr->x - camX - half, pr->y - camY - half * 2);
        u16 flicker = pr->type == PROP_CANDLE && ((vtimer >> 3) & 1);   // candle flame wavers
        u16 tile = chest ? GFX_CHESTS + ((pr->type - PROP_CHEST_BRONZE) * 2 + !pr->alive) * GFX_CHEST_TILES
                 : crate ? GFX_CRATE : GFX_PROPS + pr->type * 4;
        VDP_setSpriteFull(SPRITE_PROPS + i, pr->x - camX - half, shown ? pr->y - camY - half * 2 : -64,
                          chest || crate ? SPRITE_SIZE(4, 4) : SPRITE_SIZE(2, 2),
                          TILE_ATTR_FULL(PAL2, 1, 0, flicker, tile), SPRITE_PROPS + i + 1);
    }    for (u8 i = 0; i < MAX_PICKUPS; i++)
    {
        const Pickup *pk = &lv.pickups[i];
        u8 index = SPRITE_PICKUPS + i, link = i + 1 < MAX_PICKUPS ? index + 1 : SPRITE_HUD;
        s16 x = (pk->x >> 8) - camX, y = (pk->y >> 8) - camY;
        if (pk->type == PICKUP_NONE || offScreen(x - 8, y - 20))
            VDP_setSpriteFull(index, 0, -64, SPRITE_SIZE(1, 1), 0, link);
        else if (pk->type == PICKUP_COIN)
            VDP_setSpriteFull(index, x - 4, y - 7, SPRITE_SIZE(1, 1), TILE_ATTR_FULL(PAL2, 1, 0, (vtimer >> 3) & 1, GFX_TILE_COIN), link);
        else if (pk->type == PICKUP_KEY)   // bobbing a little over the ground
            VDP_setSpriteFull(index, x - 8, y - 18 - ((vtimer >> 4) & 1), SPRITE_SIZE(2, 2), TILE_ATTR_FULL(PAL2, 1, 0, 0, GFX_KEY), link);
        else if (pk->type == PICKUP_HEART || (pk->type == PICKUP_ITEM && pk->itemId == ITEM_HEART))
            VDP_setSpriteFull(index, x - 4, y - 12, SPRITE_SIZE(1, 1), TILE_ATTR_FULL(PAL1, 1, 0, 0, GFX_TILE_HEART), link);
        else if (pk->type == PICKUP_ITEM)
            VDP_setSpriteFull(index, x - 8, y - 20, SPRITE_SIZE(2, 2), TILE_ATTR_FULL(PAL2, 1, 0, 0, itemTile(pk->itemId)), link);
        else VDP_setSpriteFull(index, 0, -64, SPRITE_SIZE(1, 1), 0, link);
    }
    // HUD, last in the chain (behind the other sprites), over the room: the window's old rows.
    static const u8 HUD[10][5] =   // x, y (tiles), width, height, first tile offset
    {
        { 1, 0, 4, 1, 0 }, { 5, 0, 4, 1, 4 }, { 9, 0, 4, 1, 8 },    // hearts
        { 1, 1, 4, 1, 0 }, { 5, 1, 4, 1, 4 }, { 9, 1, 2, 1, 8 },    // light
        { 1, 2, 4, 1, 0 },                                          // coins
        { 34, 0, 4, 3, 0 }, { 38, 0, 1, 3, 12 },                    // minimap
        { 6, 2, 2, 1, 0 },                                          // keys
    };
    for (u8 k = 0; k < 10; k++)
    {
        u16 base = k < 3 ? GFX_HUD_HEARTS : k < 6 ? GFX_HUD_LIGHT : k == 6 ? GFX_HUD_COINS : k < 9 ? GFX_HUD_MAP : GFX_HUD_KEYS;
        u16 pal = k < 3 ? PAL1 : (k < 6 && player.corrupted) ? PAL3 : PAL2;
        VDP_setSpriteFull(SPRITE_HUD + k, HUD[k][0] * 8, HUD[k][1] * 8, SPRITE_SIZE(HUD[k][2], HUD[k][3]),
                          TILE_ATTR_FULL(pal, 1, 0, 0, base + HUD[k][4]), k < 9 ? SPRITE_HUD + k + 1 : 0);
    }
    VDP_updateSprites(SPRITE_COUNT, DMA_QUEUE);
}

static void hideSprites(void)
{
    for (u8 i = 0; i < SPRITE_COUNT; i++) VDP_setSpritePosition(i, 0, -64);
    VDP_updateSprites(SPRITE_COUNT, DMA_QUEUE);
}

// HUD (does not scroll): hearts and light bar top left, minimap of the rooms around
// top right. Each part is redrawn only when what it shows has changed.
static u8 hudHp = 0xFF, hudMaxHp = 0xFF, hudLight = 0xFF, hudCell = 0xFF, hudCorrupted = 0xFF, hudKeys = 0xFF;
static u16 hudCoins = 0xFFFF;
static u16 itemMessage;   // frames left showing a message (the item just taken, its line)

// The HUD is sprites, not the window plane: the window would hide plane A, the room, and its doors
// in the top rows. Each part's tiles are composed in its own RAM buffer (the DMA queue reads them at
// the next vertical blank) and sent only when what it shows changes.
static u32 hudHearts[12 * 8], hudLightTiles[10 * 8], hudMap[15 * 8], hudCoinTiles[4 * 8], hudKeyTiles[2 * 8];

static void copyTile(u32 *dst, const u32 *src)
{
    if (src) memcpy(dst, src, 32);
    else memset(dst, 0, 32);
}

// A picture drawn in colour 15, in colour c instead.
static void recolourTile(u32 *dst, const u32 *src, u8 c)
{
    for (u8 y = 0; y < 8; y++)
    {
        u32 line = 0;
        for (s8 x = 7; x >= 0; x--)
        {
            u8 v = (src[y] >> (x * 4)) & 15;
            line = (line << 4) | (v ? c : 0);
        }
        dst[y] = line;
    }
}

static void drawMinimap(void)
{
    // 5 x 3 rooms around the current one, Isaac-style: filled = here, outline = known. One sprite
    // palette (PAL2) for all: the kind of room is the colour (2 plain, 15 special, 4 boss, 13 Void).
    for (s8 dx = -2; dx <= 2; dx++)
        for (s8 dy = -1; dy <= 1; dy++)
        {
            u32 *dst = &hudMap[((dx + 2) * 3 + dy + 1) * 8];   // sprite tiles go column by column
            s16 x = lv.cellX + dx, y = lv.cellY + dy;
            if (x < 0 || y < 0 || x >= FLOOR_W || y >= FLOOR_H || !lv.visited[y][x])
            {
                copyTile(dst, NULL);
                continue;
            }
            u8 t = lv.floor.type[y][x], c = 2;
            if (t == ROOM_BOSS) c = 4;
            else if (t >= ROOM_UPGRADE) c = 15;
            if (level_cellInVoid(&lv, x, y) && t != ROOM_SECRET && t != ROOM_SUPER_SECRET) c = 13;
            recolourTile(dst, gfx_hudPicture(dx == 0 && dy == 0 ? 5 : 6), c);
        }
    VDP_loadTileData(hudMap, GFX_HUD_MAP, 15, DMA_QUEUE);
}

static void drawHud(void)
{
    if (player.hp != hudHp || player.maxHp != hudMaxHp)
    {
        hudHp = player.hp;
        hudMaxHp = player.maxHp;
        for (u8 i = 0; i < 12; i++)   // one heart = 2 hit points
            copyTile(&hudHearts[i * 8], i * 2 >= player.maxHp ? NULL
                     : gfx_hudPicture(player.hp >= i * 2 + 2 ? 0 : player.hp == i * 2 + 1 ? 1 : 2));
        VDP_loadTileData(hudHearts, GFX_HUD_HEARTS, 12, DMA_QUEUE);
    }
    u8 steps = (u32) player.light * 10 / player.lightMax;
    if (steps != hudLight)
    {
        hudLight = steps;
        for (u8 i = 0; i < 10; i++) copyTile(&hudLightTiles[i * 8], gfx_hudPicture(i < steps ? 3 : 4));
        VDP_loadTileData(hudLightTiles, GFX_HUD_LIGHT, 10, DMA_QUEUE);
    }
    if (player.corrupted != hudCorrupted)
    {
        hudCorrupted = player.corrupted;
        gfx_setPlayerCorrupted(player.corrupted);
    }
    // Minimap: on a room change, and once a second for the Void colours.
    u8 cell = lv.cellY * FLOOR_W + lv.cellX;
    if (cell != hudCell || !(vtimer & 63))
    {
        hudCell = cell;
        drawMinimap();
    }
    if (player.coins != hudCoins)
    {
        hudCoins = player.coins;
        u16 n = player.coins > 999 ? 999 : player.coins;
        copyTile(hudCoinTiles, gfx_coinPicture());
        u8 d[3] = { n / 100, n / 10 % 10, n % 10 }, first = n >= 100 ? 0 : n >= 10 ? 1 : 2;
        for (u8 k = 0; k < 3; k++)   // left-aligned after the coin, light (colour 2)
        {
            u8 at = k + first;
            if (at < 3) recolourTile(&hudCoinTiles[(k + 1) * 8], gfx_digitPicture(d[at]), 2);
            else copyTile(&hudCoinTiles[(k + 1) * 8], NULL);
        }
        VDP_loadTileData(hudCoinTiles, GFX_HUD_COINS, 4, DMA_QUEUE);
    }
    // Keys: the small key and how many (hidden while there are none).
    if (player.keys != hudKeys)
    {
        hudKeys = player.keys;
        copyTile(hudKeyTiles, hudKeys ? gfx_keyPicture() : NULL);
        if (hudKeys) recolourTile(&hudKeyTiles[8], gfx_digitPicture(hudKeys > 9 ? 9 : hudKeys), 2);
        else copyTile(&hudKeyTiles[8], NULL);
        VDP_loadTileData(hudKeyTiles, GFX_HUD_KEYS, 2, DMA_QUEUE);
    }
    // Shop price tags under the wares (the small shop room never scrolls).
    if (lv.shopChanged)
    {
        lv.shopChanged = 0;
        for (u8 i = 0; i < 3; i++)
        {
            const Pickup *pk = &lv.pickups[i];
            if (pk->type != PICKUP_ITEM) continue;
            char tag[4];
            sprintf(tag, "%u", pk->price);
            VDP_setTextPalette(player.coins >= pk->price ? PAL2 : PAL1);
            // On the room plane, in the air above the ware (the shop room never scrolls).
            VDP_drawTextBG(ROOM_PLANE, tag, (pk->x >> 8) / 8 - (pk->price >= 10), (pk->y >> 8) / 8 - 4);
        }
    }
    if (itemMessage && --itemMessage == 0)
    {
        VDP_clearTileMapRect(WINDOW, 0, 0, 64, 3);
        VDP_setWindowVPos(FALSE, 0);
    }
}

static void drawCentred(const char *text, u16 row)
{
    u16 len = 0;
    while (text[len]) len++;
    VDP_drawText(text, 22 - len / 2, row);
}

// Window rows 1 and 2, between the light bar / coins and the minimap: a line (row 2), or a
// title over it (row 1). The window covers the top 3 rows only while a message is up.
static void showText2(const char *title, const char *line)
{
    VDP_clearTileMapRect(WINDOW, 0, 0, 64, 3);   // the rest of the window map holds decor tiles (gfx.h)
    VDP_setWindowVPos(FALSE, 3);
    VDP_setTextPalette(PAL0);
    if (title) drawCentred(title, 1);
    drawCentred(line, 2);
    itemMessage = IS_PAL_SYSTEM ? 100 : 120;
}

static void showText(const char *line)
{
    showText2(NULL, line);
}

static void forceHud(void)
{
    hudHp = hudMaxHp = hudLight = hudCell = hudCorrupted = 0xFF;
    hudCoins = 0xFFFF;
    hudKeys = 0xFF;
    lv.shopChanged = 1;
}
#ifdef DEBUG_HUD
static void drawDebug(void)
{
    char line[41];
    VDP_setTextPalette(PAL0);
    sprintf(line, "X%4d Y%4d VX%5d VY%5d %c%c%c ", (s16) (player.x >> 8), (s16) (player.y >> 8),
            player.vx, player.vy, player.onGround ? 'G' : '-', player.crouching ? 'C' : '-',
            player_attackActive(&player) ? 'A' : '-');
    VDP_drawTextBG(BG_A, line, 1, 27);
}
#endif

// Room screen: sky on FAR_PLANE (B, parallax), room on ROOM_PLANE (A, high priority), HUD in sprites;
// the window plane only for messages.
static void enterRoom(void)
{
    mode = MODE_ROOM;
    VDP_setWindowVPos(FALSE, 0);
    VDP_setHilightShadow(TRUE);
    VDP_setScrollingMode(HSCROLL_LINE, VSCROLL_PLANE);
    VDP_setTextPlane(WINDOW);
    VDP_clearTileMapRect(WINDOW, 0, 0, 64, 3);   // the rest of the window map holds decor tiles (gfx.h)
    gfx_loadDecor();
    gfx_drawFar();
    decorCell = 0xFF;   // a new floor can start in the same cell
    drawRoom();
    forceHud();
    itemMessage = 0;
}

static void enterMap(void)
{
    mode = MODE_MAP;
    VDP_setWindowVPos(FALSE, 0);
    VDP_setHilightShadow(FALSE);
    VDP_setTextPlane(BG_A);
    VDP_setScrollingMode(HSCROLL_PLANE, VSCROLL_PLANE);
    VDP_setHorizontalScroll(BG_A, 0);
    VDP_setVerticalScroll(BG_A, 0);
    VDP_setHorizontalScroll(BG_B, 0);
    VDP_setVerticalScroll(BG_B, 0);
    hideSprites();
    drawMap();
}

// On the map the Void keeps closing (level_update only runs in rooms): shrink it here, and
// redraw the map once per second.
static void updateMapVoid(void)
{
    static u16 frames;
    if (lv.voidRunning)
    {
        lv.voidRadiusFx = lv.voidRadiusFx > lv.voidRate ? lv.voidRadiusFx - lv.voidRate : 0;
        if (!lv.voidRadiusFx) lv.voidRunning = 0;
    }
    if (++frames >= (IS_PAL_SYSTEM ? 50 : 60))
    {
        frames = 0;
        drawMap();
    }
}
// ---------------------------------------------------------------- main

static u16 readPad(void)
{
#ifdef DEBUG_SCRIPT
    // Frame-exact replay of tools/script.h; the game freezes when the script ends.
    static u16 step = 0, frame = 0;
    if (step >= sizeof(SCRIPT) / sizeof(SCRIPT[0]))
    {
        VDP_drawTextBG(BG_A, "FIN DU SCRIPT", 26, 26);   // not the window: decor tiles live there
        while (TRUE) SYS_doVBlankProcess();
    }
    u16 pad = SCRIPT[step][1];
    if (++frame >= SCRIPT[step][0])
    {
        step++;
        frame = 0;
    }
    return pad;
#else
    return JOY_readJoypad(JOY_1);
#endif
}

// Floor won (placeholder for the illustrated scene): the safe circle bursts open again and the
// world turns back to normal, then the gem screen, then the next floor.
static u8 gems, bossesInTime;
static u16 wonFrames;

// Big centred messages: the window plane covers the whole screen for a moment (the room on plane B
// still shows through its transparent pixels).
static void fullWindow(void)
{
    VDP_setWindowVPos(FALSE, 28);
    VDP_clearPlane(WINDOW, TRUE);
}

static void startFloorWon(void)
{
    wonFrames = 1;
    if (!lv.bossStrong) bossesInTime++;   // every boss reached in time: boss rush (later)
}

static void updateFloorWon(void)
{
    u16 grow = IS_PAL_SYSTEM ? 75 : 90, total = grow + (IS_PAL_SYSTEM ? 150 : 180);
    char line[41];
    wonFrames++;
    if (wonFrames <= grow)
    {
        lv.voidRadiusFx += (lv.voidStartFx - lv.voidRadiusFx) / 12 + (8 << 8);
        if (lv.voidRadiusFx > lv.voidStartFx) lv.voidRadiusFx = lv.voidStartFx;
        refreshVoid();
    }
    else if (wonFrames == grow + 1)
    {
        fullWindow();
        VDP_setTextPalette(PAL0);
        sprintf(line, "GEMME DE LA VIE  %u/7", gems);
        VDP_drawText(line, 10, 10);
        VDP_drawText(lv.gemTaken ? "LE GARDIEN TE LEGUE UN POUVOIR" : "TU AS LAISSE LA GEMME...", lv.gemTaken ? 5 : 8, 13);
        VDP_setTextPalette(lv.bossStrong ? PAL3 : PAL2);
        VDP_drawText(lv.bossStrong ? "LE NEANT L'AVAIT ATTEINT..." : "ARRIVE AVANT LE NEANT !", 7, 16);
    }
    else if (wonFrames >= total)
    {
        if (depth < 7) depth++;
        newFloor(random() ^ vtimer);   // health and upgrades are kept
        wonFrames = 0;
        enterRoom();
        return;
    }
    drawSprites();
}

static void updateRoom(u16 pad, u16 pressed)
{
    if (wonFrames)
    {
        updateFloorWon();
        return;
    }    if (deathFrames)
    {
        // Dead: the message stays two seconds, then a new floor starts.
        if (--deathFrames == 0)
        {
            player_init(&player, 0, 0);   // new run: full health, no upgrades
            depth = 1;
            newFloor(random() ^ vtimer);
            enterRoom();
        }
        return;
    }
    if (pressed & BUTTON_START)
    {
        enterMap();
        return;
    }
    // A blow that lands freezes everything for a few frames: the eye gets the time to see it.
    static u8 hitStop;
    if (hitStop)
    {
        hitStop--;
        drawSprites();
        return;
    }
    player_update(&player, &lv.room, pad);
    u8 events = level_update(&lv, &player);
    hitStop = lv.enemies.hitStop;
    lv.enemies.hitStop = 0;
    if (events & LEVEL_REDRAW) drawRoom();
    if (events & LEVEL_ITEM) showText2(player_itemName(lv.lastItem), player_itemPhrase(lv.lastItem));
    if (events & LEVEL_MESSAGE)
        // No name on a ware (Isaac-style: the items are known by their look).
        showText(lv.message == MSG_FULL_HEALTH ? "VIE PLEINE" : lv.message == MSG_BUY ? "HAUT : ACHETER"
                 : lv.message == MSG_TAKE ? "HAUT : PRENDRE" : lv.message == MSG_EXIT ? "HAUT : NIVEAU SUIVANT"
                 : lv.message == MSG_ENTER ? "HAUT : ENTRER"
                 : lv.message == MSG_NEED_KEY ? "IL FAUT UNE CLE" : lv.message == MSG_UNLOCKED ? "LA PORTE S'OUVRE"
                 : "PAS ASSEZ DE PIECES");
    if (events & LEVEL_GEM)
    {
        gems++;
        showText2("GEMME DE LA VIE", "LE GARDIEN TE LA LEGUE");
    }
    if (events & LEVEL_KEY) showText2("UNE CLE", "POUR UN CADENAS");
    if (events & LEVEL_EXIT)
    {
        startFloorWon();
        return;
    }
    refreshVoid();
    updateCamera();
    scrollCamera();
    drawSprites();
    drawHud();
#ifdef DEBUG_HUD
    drawDebug();
#endif
    if (player.hp <= 0)
    {
        deathFrames = IS_PAL_SYSTEM ? 100 : 120;
        fullWindow();
        VDP_setTextPalette(PAL1);
        VDP_drawText("LE NEANT T'A EU...", 11, 13);
    }
}

int main(bool hardReset)
{
    (void) hardReset;
    VDP_setPlaneSize(64, 32, TRUE);
    VDP_setTextPriority(1);
    gfx_load();
    VDP_resetSprites();
    player_setRegion(IS_PAL_SYSTEM);
    enemies_setRegion(IS_PAL_SYSTEM);
    level_setRegion(IS_PAL_SYSTEM);

    player_init(&player, 0, 0);
    newFloor(0x1234);
#ifdef DEBUG_ENEMIES
    // Diagnostic build (tools/replay.ps1 -Flags "-DDEBUG_ENEMIES"): one enemy of each kind around the
    // hero in the first room, to look at their poses.
    {
        static const s16 SPAWN[5][2] =
        {
            { ENEMY_WALKER, 56 }, { ENEMY_ARCHER, 120 }, { ENEMY_GUARD, -56 },
            { ENEMY_JELLY, 90 }, { ENEMY_FLYER, 0 },
        };
        for (u8 i = 0; i < 5; i++)
            enemies_add(&lv.enemies, SPAWN[i][0], (player.x >> 8) + SPAWN[i][1],
                        (player.y >> 8) - (SPAWN[i][0] == ENEMY_FLYER ? 70 : 0), 0);
    }
#endif
#ifdef DEBUG_CARAVAN
    // Diagnostic build: in the caravan's room, a little left of the caravan.
    if (lv.shopX != 0xFF)
    {
        level_enter(&lv, &player, lv.carX, lv.carY);
        enemies_clear(&lv.enemies);
        player_place(&player, lv.caravanX - 48, lv.caravanY);
    }
#endif
#ifdef DEBUG_KEYS
    // Diagnostic build: in the room before the upgrade room, by its padlock, with one key.
    if (lv.lockX != 0xFF)
    {
        level_enter(&lv, &player, lv.lockX, lv.lockY);
        enemies_clear(&lv.enemies);
        player_place(&player, lv.padlockX + (lv.lockDir == DOOR_LEFT ? 40 : lv.lockDir == DOOR_RIGHT ? -40 : 24),
                     lv.room.h * ROOM_TILE - 2 * ROOM_TILE);
        player.keys = 1;
    }
#endif
#ifdef DEBUG_BOSS_DOWN
    // Diagnostic build: straight into the boss room, the boss just beaten (gem and exit door).
    level_enter(&lv, &player, lv.floor.voidX, lv.floor.voidY);
    {
        s8 slot = enemies_bossSlot(&lv.enemies);
        if (slot >= 0) lv.enemies.e[slot].deathTimer = 1;
    }
    player_place(&player, 60, lv.room.h * ROOM_TILE - 2 * ROOM_TILE);
#endif
    enterRoom();

    u16 prevPad = 0;
    while (TRUE)
    {
        u16 pad = readPad();
        u16 pressed = pad & ~prevPad;
        prevPad = pad;

        if (mode == MODE_ROOM) updateRoom(pad, pressed);
        else if (pressed & BUTTON_START) enterRoom();
        else
        {
            updateMap(pressed);
            updateMapVoid();
        }
        SYS_doVBlankProcess();
    }
    return 0;
}
